function acceptImage(img,name){if(image&&!confirm('開啟新圖片或專案會取代目前內容。請確認已儲存需要保留的專案或 PNG。'))return false;sourceImage=img;margins={top:0,bottom:0,left:0,right:0};syncMargins();image=img;filename=name.replace(/\.[^.]+$/,'')||'教學截圖';items=[];selected=-1;drag=null;history=[snapshot()];historyIndex=0;canvas.width=img.width;canvas.height=img.height;$('empty').hidden=true;$('canvasWrap').hidden=false;$('filename').textContent=name;$('dimensions').textContent=img.width+' × '+img.height+' px';$('nextNumber').value=1;setTool('rect');fit();toast('圖片已開啟，拖曳即可新增紅框');return true}
async function loadFile(file){if(!file)return;if(!/^image\/(png|jpeg|webp|gif)$/.test(file.type)){toast('請選擇 PNG、JPG、WebP 或 GIF 圖片');return}if(file.size>30*1024*1024){toast('請使用 30 MB 以下的圖片');return}const url=URL.createObjectURL(file);try{const img=new Image();img.src=url;await img.decode();if(img.width*img.height>32000000||img.width>16000||img.height>16000)throw new Error('too-large');acceptImage(img,file.name);if(file.type==='image/gif')toast('GIF 會以靜態圖片開啟')}catch(e){toast(e.message==='too-large'?'圖片尺寸過大，請縮小後再開啟':'無法讀取圖片，請換一張再試')}finally{URL.revokeObjectURL(url)}}
