$('saveProject').onclick=()=>{try{downloadBlob(new Blob([JSON.stringify(projectData())],{type:'application/json'}),filename+'.screenshot.json');toast('專案已下載，下次使用「開啟專案」繼續編輯')}catch{toast('無法儲存專案，請再試一次')}};
function validateProject(data){if(!data||data.format!=='screenshot-studio'||data.version!==1)throw Error('這不是支援的教學截圖專案');if(typeof data.filename!=='string'||data.filename.length>300||typeof data.image!=='string'||!/^data:image\/png;base64,[A-Za-z0-9+/=\r\n]+$/.test(data.image))throw Error('專案圖片資料不正確');if(!data.margins||!['top','bottom','left','right'].every(k=>Number.isInteger(data.margins[k])&&data.margins[k]>=0&&data.margins[k]<=2000))throw Error('專案留白設定不正確');if(!Array.isArray(data.items)||data.items.length>5000)throw Error('專案標註數量不正確');for(const o of data.items){if(!o||!['rect','arrow','number','text','mosaic','step','mask'].includes(o.type)||!['x','y','w','h','size','width'].every(k=>Number.isFinite(o[k])&&Math.abs(o[k])<=64000)||o.size<16||o.size>160||o.width<2||o.width>24||typeof o.color!=='string'||!/^#[0-9a-f]{6}$/i.test(o.color))throw Error('專案標註格式不正確');if(['text','step'].includes(o.type)&&(typeof o.text!=='string'||o.text.length>20000))throw Error('專案文字格式不正確');if(['number','step'].includes(o.type)&&(!Number.isInteger(o.n)||o.n<1||o.n>999))throw Error('專案編號格式不正確');if(o.type==='step'&&(o.w<160||o.w>1600))throw Error('步驟框寬度不正確')}return data}
async function loadProject(file){if(!file)return;try{if(file.size>100*1024*1024)throw Error('專案檔案超過 100 MB');const data=validateProject(JSON.parse(await file.text()));const img=new Image();img.src=data.image;await img.decode();if(img.width>16000||img.height>16000||img.width*img.height>32000000)throw Error('專案圖片過大');const padded=paddedImage(img,data.margins);if(!acceptImage(img,data.filename))return;filename=data.filename;image=padded;margins={top:data.margins.top,bottom:data.margins.bottom,left:data.margins.left,right:data.margins.right};items=structuredClone(data.items);canvas.width=image.width;canvas.height=image.height;history=[snapshot()];historyIndex=0;syncMargins();$('nextNumber').value=Number.isInteger(data.nextNumber)&&data.nextNumber>=1&&data.nextNumber<=999?data.nextNumber:1;$('dimensions').textContent=image.width+' × '+image.height+' px';setTool('select');fit();toast('專案已開啟，所有標註都可以繼續修改')}catch(e){toast(e instanceof SyntaxError?'無法讀取專案，請選擇儲存的 JSON 檔':e.message||'無法開啟專案')}}
$('openProject').onclick=()=>$('projectFile').click();$('projectFile').onchange=e=>{loadProject(e.target.files[0]);e.target.value=''};


function stepLayout(o){const pad=o.size*.5,badge=o.size*1.36,gap=o.size*.4,w=Math.max(o.w,badge+pad*2+gap+o.size),available=w-pad*2-badge-gap,lines=[];ctx.save();ctx.font='600 '+o.size+'px "Microsoft JhengHei",sans-serif';for(const paragraph of o.text.split('\n')){let line='';for(const char of paragraph){if(line&&ctx.measureText(line+char).width>available){lines.push(line);line=char}else line+=char}lines.push(line)}ctx.restore();return{w,h:Math.max(badge,lines.length*o.size*1.3)+pad*2,pad,badge,gap,lines}}
function drawStep(c,o){const l=stepLayout(o);c.fillStyle='#fff';c.beginPath();c.roundRect(o.x,o.y,l.w,l.h,Math.min(16,o.size*.35));c.fill();c.strokeStyle=o.color;c.lineWidth=o.width;c.stroke();const bx=o.x+l.pad+l.badge/2,by=o.y+l.pad+l.badge/2;c.fillStyle=o.color;c.beginPath();c.arc(bx,by,l.badge/2,0,Math.PI*2);c.fill();const rgb=o.color.slice(1).match(/../g).map(v=>parseInt(v,16));c.fillStyle=(rgb[0]*.299+rgb[1]*.587+rgb[2]*.114)>165?'#172033':'#fff';c.font='700 '+o.size*(String(o.n).length>2?.66:.9)+'px sans-serif';c.textAlign='center';c.textBaseline='middle';c.fillText(o.n,bx,by+o.size*.03);c.fillStyle='#172033';c.font='600 '+o.size+'px "Microsoft JhengHei",sans-serif';c.textAlign='left';c.textBaseline='top';l.lines.forEach((line,i)=>c.fillText(line,o.x+l.pad+l.badge+l.gap,o.y+l.pad+i*o.size*1.3))}
$('stepWidth').addEventListener('input',()=>{if(items[selected]?.type==='step'){items[selected].w=+$('stepWidth').value;render()}});
$('stepWidth').addEventListener('change',commit);
$('stepNumber').addEventListener('change',()=>{if(items[selected]?.type==='step'){const n=Number($('stepNumber').value);if(Number.isInteger(n)&&n>=1&&n<=999){items[selected].n=n;commit()}else{$('stepNumber').value=items[selected].n;toast('編號請輸入 1–999')}}});

function paintAnnotations(c){items.filter(o=>o.type!=='mask').forEach(o=>drawObject(c,o));items.filter(o=>o.type==='mask').forEach(o=>drawObject(c,o))}

$('copyImage').onclick=async()=>{if(!image)return;if(!navigator.clipboard?.write||!window.ClipboardItem){toast('此瀏覽器不支援複製圖片，請使用「下載 PNG」');return}const button=$('copyImage');button.disabled=true;try{const blobPromise=new Promise((resolve,reject)=>makeExport().toBlob(blob=>blob?resolve(blob):reject(Error()),'image/png'));await navigator.clipboard.write([new ClipboardItem({'image/png':blobPromise})]);toast('已複製圖片，可以貼到 LINE、Email 或文件')}catch{toast('無法複製圖片，請允許剪貼簿權限，或使用「下載 PNG」')}finally{button.disabled=!image}};
let mergeImages=[],mergeBusy=false,mergeToken=0;
function mergeStatus(){const width=Number($('mergeWidth').value),gap=Number($('mergeGap').value);if(!Number.isInteger(width)||width<200||width>4000||!Number.isInteger(gap)||gap<0||gap>500)throw Error('長圖寬度需為 200–4000，間距需為 0–500');const heights=mergeImages.map(o=>Math.round(o.img.height*Math.min(1,width/o.img.width)));const height=heights.reduce((a,b)=>a+b,0)+Math.max(0,heights.length-1)*gap;if(height>16000||height*width>32000000)throw Error('長圖尺寸過大，請減少圖片、寬度或間距');return{width,gap,heights,height}}
function renderMerge(){const list=$('mergeList');list.replaceChildren();mergeImages.forEach((o,i)=>{const row=document.createElement('li'),thumb=document.createElement('canvas'),text=document.createElement('span');thumb.width=72;thumb.height=52;const c=thumb.getContext('2d'),scale=Math.min(72/o.img.width,52/o.img.height);c.drawImage(o.img,0,0,o.img.width*scale,o.img.height*scale);text.textContent=(i+1)+'. '+o.name;row.append(thumb,text);for(const [label,delta]of [['上移',-1],['下移',1],['移除',0]]){const b=document.createElement('button');b.textContent=label;b.type='button';b.setAttribute('aria-label',label+' '+o.name);b.disabled=mergeBusy||(delta===-1&&i===0)||(delta===1&&i===mergeImages.length-1);b.onclick=()=>{if(delta){[mergeImages[i],mergeImages[i+delta]]=[mergeImages[i+delta],mergeImages[i]]}else mergeImages.splice(i,1);renderMerge()};row.append(b)}list.append(row)});$('buildMerge').disabled=mergeBusy||mergeImages.length<2;$('mergeAdd').disabled=mergeBusy;$('mergeCurrent').disabled=mergeBusy||!image;try{const m=mergeStatus();$('mergeSummary').textContent=mergeBusy?'正在讀取圖片…':mergeImages.length?mergeImages.length+' 張 · '+m.width+' × '+m.height+' px':'選擇至少兩張圖片，依序由上往下排列。'}catch(e){$('mergeSummary').textContent=e.message;$('buildMerge').disabled=true}}
$('mergeOpen').onclick=()=>{mergeImages=[];$('mergeDialog').append($('toast'));$('mergeDialog').showModal();renderMerge()};
$('mergeClose').onclick=()=>$('mergeDialog').close();
$('mergeDialog').addEventListener('close',()=>{document.body.append($('toast'));mergeToken++;mergeImages=[];mergeBusy=false});
$('mergeAdd').onclick=()=>$('mergeFiles').click();
$('mergeWidth').oninput=$('mergeGap').oninput=renderMerge;
$('mergeCurrent').onclick=()=>{if(mergeImages.length>=20){toast('最多合併 20 張圖片');return}if(mergeImages.reduce((n,o)=>n+o.img.width*o.img.height,0)+image.width*image.height>64000000){toast('合併圖片總尺寸過大，請減少張數');return}mergeImages.push({name:filename+'（含目前標註）',img:makeExport()});renderMerge()};
$('mergeFiles').onchange=async e=>{const files=[...e.target.files];e.target.value='';if(!files.length)return;if(mergeImages.length+files.length>20){toast('最多合併 20 張圖片');return}const token=++mergeToken;mergeBusy=true;renderMerge();const loaded=[];try{let pixels=mergeImages.reduce((n,o)=>n+o.img.width*o.img.height,0);for(const file of files){if(!/^image\/(png|jpeg|webp|gif)$/.test(file.type)||file.size>30*1024*1024)throw Error('請選擇 30 MB 以下的 PNG、JPG、WebP 或 GIF');const url=URL.createObjectURL(file);try{const img=new Image();img.src=url;await img.decode();pixels+=img.width*img.height;if(pixels>64000000||img.width>16000||img.height>16000)throw Error('所選圖片總尺寸過大，請減少張數或縮小圖片');loaded.push({name:file.name,img})}finally{URL.revokeObjectURL(url)}}if(token===mergeToken)mergeImages.push(...loaded)}catch(e){if(token===mergeToken)toast(e.message||'無法讀取圖片')}finally{if(token===mergeToken){mergeBusy=false;renderMerge()}}};
$('buildMerge').onclick=()=>{if(mergeBusy||mergeImages.length<2)return;try{const m=mergeStatus(),out=document.createElement('canvas');out.width=m.width;out.height=m.height;const c=out.getContext('2d');c.fillStyle='#fff';c.fillRect(0,0,out.width,out.height);let y=0;mergeImages.forEach((o,i)=>{const w=Math.min(o.img.width,m.width);c.drawImage(o.img,(m.width-w)/2,y,w,m.heights[i]);y+=m.heights[i]+m.gap});if(acceptImage(out,'教學長圖.png')){$('mergeDialog').close();toast('長圖已建立，可繼續加入標註或下載 PNG')}}catch(e){toast(e.message)}};
